INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"00a2fc51-4f28-514a-9ee2-1b95b6bf78b4","title":"Business Studies · Grade 10 · Term 2: Business sectors and ownership","subject":"Business Studies","grade":"Grade 10","questions":[{"question":"A bakery turns flour into bread. Which economic sector describes this production?","options":["Primary","Tertiary","Secondary","Public sector only"],"correct_index":2,"explanation":"The secondary sector transforms raw materials into products. Farming wheat is primary; selling services is tertiary."},{"question":"Which feature usually distinguishes a sole proprietor?","options":["Separate legal personality with shareholders by definition","Government ownership only","At least seven partners","One owner with unlimited personal liability"],"correct_index":3,"explanation":"A sole proprietor owns the business personally and generally bears its debts. This is a risk to consider alongside control and simplicity."},{"question":"A business supports a local reading programme. Which concept best fits?","options":["Corporate social responsibility","Price fixing","Market segmentation only","Stock control"],"correct_index":0,"explanation":"Supporting community well-being can be part of corporate social responsibility. Assess its real benefits rather than assuming every donation solves the issue."},{"question":"Why can unemployment affect a local shop's sales?","options":["It guarantees higher sales for every shop","Lower household income can reduce demand","It eliminates all business costs","It changes a shop into a primary-sector business"],"correct_index":1,"explanation":"Unemployment can reduce customers' spending power. Businesses should examine local evidence and demand patterns rather than assume identical effects everywhere."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Business sectors and ownership. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","bst"],"metadata":{"term":2,"focus":"Business sectors and ownership","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"9c02e1ac-45ac-590e-8a4c-f50c5bddf326","title":"Business Studies · Grade 10 · Term 3: Problem solving, research and business plans","subject":"Business Studies","grade":"Grade 10","questions":[{"question":"Customers complain about long queues. What should the business do first in a structured problem-solving process?","options":["Buy equipment before checking causes","Blame customers immediately","Copy a random competitor without analysis","Define and investigate the queue problem"],"correct_index":3,"explanation":"A clear problem definition and evidence help identify causes. Solutions should address the cause rather than a guessed symptom."},{"question":"Which example is primary market research?","options":["Surveying the shop's customers directly","Reading last year's published industry report","Copying a newspaper statistic","Using an old public census table"],"correct_index":0,"explanation":"Primary research collects new data for the current purpose. Published existing information is secondary research."},{"question":"Why include a cash-flow forecast in a business plan?","options":["To guarantee every sale is cash","To anticipate when cash may be received and paid","To replace a description of customers","To prove the business cannot fail"],"correct_index":1,"explanation":"Timing matters: a profitable business can still run short of cash. A forecast supports planning, not certainty."},{"question":"Which slide design best supports a short business presentation?","options":["A dense page of tiny text","Unlabelled figures with no source","A readable chart with a clear label and explained message","Animated text that hides the main point"],"correct_index":2,"explanation":"Visuals should make evidence easier to interpret. Explain units, meaning and source rather than expecting decoration to communicate the argument."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Problem solving, research and business plans. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","bst"],"metadata":{"term":3,"focus":"Problem solving, research and business plans","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"22e84c00-1d90-5648-91fc-79c8732e05e1","title":"Business Studies · Grade 10 · Term 4: Relationships and team performance","subject":"Business Studies","grade":"Grade 10","questions":[{"question":"A team has clear roles but members never share progress. What improvement is most useful?","options":["Agree regular check-ins and shared communication","Stop all communication to avoid disagreement","Let every member assume others finished","Punish questions without discussion"],"correct_index":0,"explanation":"Clear communication helps coordinate interdependent tasks and identify problems early. Roles alone do not ensure collaboration."},{"question":"A manager allocates tasks using stereotypes about gender. Why is this harmful?","options":["It is always the most accurate skills test","It can unfairly exclude capable people and damage trust","It guarantees teamwork","It makes individual skills irrelevant"],"correct_index":1,"explanation":"Fair task allocation should consider skills and development needs. Stereotyping undermines inclusion and team performance."},{"question":"Which action best handles a disagreement about a deadline?","options":["Insult the other member","Hide the deadline","Listen to both views and agree a practical plan tied to the goal","Refuse to discuss evidence"],"correct_index":2,"explanation":"Constructive conflict management focuses on the issue, evidence and achievable agreements, with follow-up responsibilities."},{"question":"How can a team assess performance meaningfully?","options":["Count only how often members smiled","Assume all busy teams succeeded","Avoid feedback entirely","Compare agreed objectives with results and discuss improvements"],"correct_index":3,"explanation":"Performance assessment needs relevant criteria and evidence. Reflect on process and outcomes to guide the next task."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Relationships and team performance. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","bst"],"metadata":{"term":4,"focus":"Relationships and team performance","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"603b8aab-0597-5c59-a9ba-b5e1f1c38d23","title":"Economics · Grade 10 · Term 2: Markets, intervention and scarcity","subject":"Economics","grade":"Grade 10","questions":[{"question":"If demand rises while supply is unchanged, what happens to equilibrium price in the standard model?","options":["It necessarily falls","It must stay identical","It becomes zero","It rises"],"correct_index":3,"explanation":"A rightward demand shift raises equilibrium price and quantity, other things equal. Distinguish a shift from movement along a demand curve."},{"question":"A binding maximum price is set below equilibrium. What may result?","options":["A shortage","A surplus by definition","No change in any market","Unlimited supply"],"correct_index":0,"explanation":"At the lower price, quantity demanded exceeds quantity supplied. A price ceiling can create a shortage if it is binding."},{"question":"What does a point inside a production possibility curve indicate?","options":["The economy is producing beyond current capacity","Resources are unemployed or used inefficiently","No scarcity exists","All resources are fully efficient by definition"],"correct_index":1,"explanation":"Inside the PPC, more output may be possible using existing resources better. A point beyond the curve requires greater capacity or technology."},{"question":"Why do economic choices have opportunity costs?","options":["All goods are free","Resources are unlimited","Choosing one option can mean giving up the next best alternative","Money is the only scarce resource"],"correct_index":2,"explanation":"Scarcity creates trade-offs. Opportunity cost is the value of the next best alternative forgone, which need not be a cash payment."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Markets, intervention and scarcity. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","eco"],"metadata":{"term":2,"focus":"Markets, intervention and scarcity","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"3b4befb2-7a09-5133-9cc3-52827f645a5b","title":"Economics · Grade 10 · Term 3: Development, population and labour","subject":"Economics","grade":"Grade 10","questions":[{"question":"What is a main benefit of a generally accepted medium of exchange over barter?","options":["It reduces the need for a double coincidence of wants","It eliminates all scarcity","It guarantees equal incomes","It prevents any price changes"],"correct_index":0,"explanation":"Money allows people to sell to one person and buy from another without each wanting exactly the other's goods."},{"question":"A country has 40 births and 25 deaths per 1 000 people, ignoring migration. Find its natural increase per 1 000.","options":["65","15","25","40"],"correct_index":1,"explanation":"Natural increase = birth rate−death rate = 40−25=15 per 1 000. Migration is a separate component of population change."},{"question":"Why is education relevant to labour productivity?","options":["It guarantees every worker a job","It makes equipment unnecessary","It can develop knowledge and skills that improve output per worker","It eliminates differences between all occupations"],"correct_index":2,"explanation":"Human-capital development can support productivity, alongside health, technology and work organisation. It does not by itself guarantee employment."},{"question":"Which action is part of collective bargaining?","options":["Customers choose a shop's logo","A firm hides wages from every worker","A worker guesses the inflation rate","Worker representatives and employers negotiate employment conditions"],"correct_index":3,"explanation":"Collective bargaining involves representatives negotiating employment matters. Its outcomes depend on the process and applicable framework."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Development, population and labour. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","eco"],"metadata":{"term":3,"focus":"Development, population and labour","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"1e3c1a34-1ff8-5319-a50e-f47f509bf41b","title":"Economics · Grade 10 · Term 4: Unemployment and economic redress","subject":"Economics","grade":"Grade 10","questions":[{"question":"A labour force has 800 employed and 200 unemployed people. Find the unemployment rate using this definition.","options":["25%","20%","80%","200%"],"correct_index":1,"explanation":"Labour force = employed+unemployed = 1 000. Rate = 200/1 000×100=20%. Do not divide only by those employed."},{"question":"Which situation best illustrates structural unemployment?","options":["A worker voluntarily takes one lunch break","All vacancies are filled instantly","Workers' skills do not match the jobs available after industry changes","A firm changes its stationery colour"],"correct_index":2,"explanation":"Structural unemployment involves a mismatch between labour supply and demand, including skills or location. Retraining may be part of a response."},{"question":"Why might public works programmes help address unemployment?","options":["They guarantee permanent jobs for everyone","They eliminate the need for training","They make project quality irrelevant","They can provide temporary paid work and useful infrastructure"],"correct_index":3,"explanation":"Public works can provide income and assets while broader employment measures develop. Their scale, duration and training content affect their impact."},{"question":"What is an aim of economic redress?","options":["Address exclusion and unequal access to economic opportunities","Preserve every historical inequality","Ban every form of economic participation","Guarantee identical outcomes without any policy evaluation"],"correct_index":0,"explanation":"Redress aims to improve fair access and participation. Policies need evidence, implementation and evaluation rather than assuming aims guarantee success."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Unemployment and economic redress. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","eco"],"metadata":{"term":4,"focus":"Unemployment and economic redress","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"bc797589-aca3-56cc-bec7-83e30e8aef97","title":"Geography · Grade 10 · Term 2: Plate tectonics and geological hazards","subject":"Geography","grade":"Grade 10","questions":[{"question":"At a constructive plate boundary, plates generally…","options":["Move apart and new crust can form","Move towards one another in every case","Remain completely motionless","Stop all volcanic activity"],"correct_index":0,"explanation":"Divergent plate movement can allow magma to rise and solidify as new crust. Identify the boundary type before predicting processes."},{"question":"Which rock forms when magma or lava cools and solidifies?","options":["Sedimentary","Igneous","Metamorphic in every case","Any rock only after fossils form"],"correct_index":1,"explanation":"Igneous rocks form through cooling of molten material. Sedimentary and metamorphic rocks form through different processes."},{"question":"What is the focus of an earthquake?","options":["The point directly above it on the surface","The largest nearby city","The point inside Earth where rupture begins","The instrument that records shaking"],"correct_index":2,"explanation":"The focus, or hypocentre, is within Earth. The epicentre is the surface point directly above it."},{"question":"Why can similar earthquakes cause different losses in two cities?","options":["Magnitude is the only possible factor","Population and infrastructure never matter","All earthquakes cause identical damage","Exposure, building quality and preparedness differ"],"correct_index":3,"explanation":"Risk depends on the hazard plus vulnerability and exposure. Safer buildings and preparation can reduce losses without preventing earthquakes."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Plate tectonics and geological hazards. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","geo"],"metadata":{"term":2,"focus":"Plate tectonics and geological hazards","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"e2c1a8a4-e39c-5d13-8b6b-790eda1d2805","title":"Geography · Grade 10 · Term 3: Population geography and migration","subject":"Geography","grade":"Grade 10","questions":[{"question":"A district has 60 000 people in 200 km². Find its population density.","options":["3 people/km²","300 people/km²","12 000 000 people/km²","30 people/km²"],"correct_index":1,"explanation":"Population density = population/area = 60 000/200 = 300 people per km². An average can hide uneven distribution."},{"question":"What may a broad base on a population pyramid suggest?","options":["Every resident is elderly","No births have occurred","A large proportion of young people","All age groups have equal numbers"],"correct_index":2,"explanation":"The base represents younger ages. Interpret the full pyramid and data context before predicting future growth."},{"question":"Which is a push factor for migration?","options":["Better jobs at the destination","Safer housing at the destination","Access to a desired university elsewhere","Loss of local employment"],"correct_index":3,"explanation":"Push factors encourage departure from an origin. Pull factors attract people towards a destination."},{"question":"Why can rural–urban migration create planning challenges?","options":["Services and housing may need to expand rapidly","It automatically reduces all urban populations","It eliminates transport demand","It means every migrant has the same experience"],"correct_index":0,"explanation":"Rapid population change can increase demand for housing, water, transport and jobs. Planning should consider varied needs and contributions."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Population geography and migration. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","geo"],"metadata":{"term":3,"focus":"Population geography and migration","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"6dcb0e63-98e5-5ee4-a0b7-92c558ec77c9","title":"Geography · Grade 10 · Term 4: Water management and flooding","subject":"Geography","grade":"Grade 10","questions":[{"question":"Why can paving land increase rapid surface runoff?","options":["Concrete absorbs every rainfall event","Paving removes gravity","Less water infiltrates through impermeable surfaces","Every paved area prevents all flooding"],"correct_index":2,"explanation":"Impermeable surfaces reduce infiltration and can speed runoff to drains and rivers. Drainage capacity and rainfall intensity also matter."},{"question":"Which action most directly supports sustainable school water use?","options":["Leave taps running to test the pipes","Ignore meter readings","Use treated drinking water for every unnecessary task","Repair leaks and monitor consumption"],"correct_index":3,"explanation":"Fixing leaks reduces avoidable losses. Monitoring shows whether savings persist and helps detect new problems."},{"question":"Why protect vegetation in a river catchment?","options":["It can slow runoff, support infiltration and reduce erosion","It guarantees no flood can ever occur","It prevents all water reaching rivers","It creates unlimited rainfall"],"correct_index":0,"explanation":"Vegetation helps regulate water movement and stabilise soil. Flood risk also depends on storm intensity, saturation and land use."},{"question":"What is a key concern when building homes on a floodplain?","options":["Guaranteed absence of flood risk","Exposure to periodic river flooding","The river can never change level","Only the paint colour of houses"],"correct_index":1,"explanation":"Floodplains are areas rivers can inundate. Site selection, warnings and flood management should account for this recurring risk."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Water management and flooding. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","geo"],"metadata":{"term":4,"focus":"Water management and flooding","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"801e3440-ba0d-5a86-ac40-e11494a6b4c3","title":"History · Grade 10 · Term 2: French Revolution and historical reasoning","subject":"History","grade":"Grade 10","questions":[{"question":"Which condition contributed to revolutionary pressures in France before 1789?","options":["Universal equal taxation already accepted by all","Financial crisis and unequal burdens within the estate system","The absence of political conflict","A fully democratic republic for centuries"],"correct_index":1,"explanation":"Fiscal crisis, privilege, inequality and new political ideas contributed to tensions. A strong answer explains their interaction rather than listing only one cause."},{"question":"What did the slogan liberty, equality and fraternity express in the French Revolution?","options":["Support for every hereditary privilege","A promise that inequality ended immediately everywhere","Ideals challenging aspects of the old political and social order","A purely military weather report"],"correct_index":2,"explanation":"The slogan expressed revolutionary ideals. Examine how far different groups experienced those ideals in practice."},{"question":"A historian studies a speech by a revolutionary leader. What should be considered?","options":["Only whether its handwriting looks attractive","That a speech must be neutral","That political speeches are always useless","Its author, audience, purpose and context"],"correct_index":3,"explanation":"A source's purpose and audience shape what it reveals and what it may omit. Bias affects interpretation but does not automatically make it useless."},{"question":"Why do historians compare accounts of political change in southern Africa after 1750?","options":["Different evidence and perspectives can challenge single-cause explanations","All oral accounts must be discarded","The first published account must always be accepted","Every source gives identical evidence"],"correct_index":0,"explanation":"Comparison and corroboration help evaluate contested interpretations. Consider chronology, context and the strengths and limits of different evidence."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: French Revolution and historical reasoning. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","hist"],"metadata":{"term":2,"focus":"French Revolution and historical reasoning","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"de779e22-5c77-5212-8e98-c9ede9443241","title":"History · Grade 10 · Term 3: Colonial expansion, war and Union","subject":"History","grade":"Grade 10","questions":[{"question":"What was one effect of colonial expansion into the interior of southern Africa?","options":["An end to every conflict","Equal political rights for all inhabitants","Changes to land control and labour relations","No effect on local societies"],"correct_index":2,"explanation":"Expansion affected land, labour, political authority and resistance. Effects varied across places and communities and should be supported with examples."},{"question":"Why is mining capitalism relevant to studying the South African War?","options":["The war had no economic context","Mining began only after 1994","Every cause can be reduced to one mine owner","Gold, capital and competing political interests shaped tensions"],"correct_index":3,"explanation":"Economic change helps explain tensions, alongside political and imperial factors. Avoid presenting one factor as the only cause."},{"question":"A source is a civilian's diary written during a war. What can it reveal especially well?","options":["That individual's experiences and perceptions at the time","A complete neutral account of every battlefield","The intentions of every government leader","The experiences of all civilians without comparison"],"correct_index":0,"explanation":"A diary provides a situated perspective. It may be valuable for lived experience while needing comparison with other sources for broader claims."},{"question":"What is a sound historical paragraph?","options":["A list of unrelated dates","A clear point supported by relevant evidence and explanation","An opinion with no evidence","A copied source with no interpretation"],"correct_index":1,"explanation":"Link the point, evidence and reasoning to the question. Evidence matters because it supports, qualifies or challenges the argument."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Colonial expansion, war and Union. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","hist"],"metadata":{"term":3,"focus":"Colonial expansion, war and Union","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"34c136f2-5384-589e-8b54-dcc34bc7e44b","title":"History · Grade 10 · Term 4: The 1913 land law and examination skills","subject":"History","grade":"Grade 10","questions":[{"question":"What was a major effect of the Natives Land Act of 1913?","options":["Providing equal land access to all","Ending racial segregation immediately","Giving every family an equal farm","Restricting African land acquisition and occupation along racial lines"],"correct_index":3,"explanation":"The law entrenched discriminatory land restrictions with major economic and social consequences. Use its historical context to explain later patterns."},{"question":"Why is Sol Plaatje's writing useful for studying the 1913 land law?","options":["It records an informed contemporary critique and experiences of its effects","It is automatically free of viewpoint","It replaces every other source","It proves every person had the same experience"],"correct_index":0,"explanation":"Plaatje offers valuable contemporary evidence. Evaluate his purpose and corroborate specific claims rather than treating any source as complete."},{"question":"What does corroborating a source mean?","options":["Copying its wording twice","Checking its claims against other relevant evidence","Ignoring its date","Assuming agreement proves perfect truth"],"correct_index":1,"explanation":"Corroboration compares evidence for support or contradiction. Independent sources and context help assess reliability."},{"question":"An essay asks to what extent a policy changed society. What must the answer do?","options":["Only define one word","List events without a position","Evaluate the degree of change with evidence and qualifications","Avoid evidence that complicates the argument"],"correct_index":2,"explanation":"An extent judgment weighs change and continuity and reaches a supported conclusion. Address counter-evidence rather than ignoring it."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: The 1913 land law and examination skills. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","hist"],"metadata":{"term":4,"focus":"The 1913 land law and examination skills","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"169d1e22-b3fc-575c-838a-e87704ec1159","title":"Tourism · Grade 10 · Term 2: Map work and domestic tourism","subject":"Tourism","grade":"Grade 10","questions":[{"question":"A traveller visits Durban from their home in Johannesburg. What type of tourism is this?","options":["Inbound international tourism","Outbound international tourism","Domestic tourism","Space tourism"],"correct_index":2,"explanation":"The traveller remains within their own country. Domestic tourism can cross provincial boundaries without becoming international tourism."},{"question":"What does a map legend explain?","options":["The exact price of every hotel","Every country's exchange rate","Only historical myths","The meaning of symbols used on that map"],"correct_index":3,"explanation":"A legend, or key, helps interpret features and services represented by symbols. Check the map's own key rather than assuming every symbol is universal."},{"question":"A route table gives 120 km from A to B and 80 km from B to C. Via B, how far is A to C?","options":["200 km","40 km","9 600 km","160 km"],"correct_index":0,"explanation":"For the stated route, add the two legs: 120+80=200 km. A direct route could differ, but it is not the route specified."},{"question":"Why can domestic tourism support local economies?","options":["All visitor spending goes abroad automatically","Visitor spending can support businesses, jobs and linked suppliers","It eliminates seasonal changes","It guarantees equal income for every resident"],"correct_index":1,"explanation":"Local spending can create direct and indirect benefits. Who benefits depends on ownership, sourcing and local linkages."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Map work and domestic tourism. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","tour"],"metadata":{"term":2,"focus":"Map work and domestic tourism","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"8d69e515-ef3b-5641-b48d-315cc9446b54","title":"Tourism · Grade 10 · Term 3: Attractions and responsible tourism","subject":"Tourism","grade":"Grade 10","questions":[{"question":"Which behaviour best protects a wildlife attraction?","options":["Feed wildlife for photographs","Remove plants as souvenirs","Leave litter near water","Keep a safe distance and follow park rules"],"correct_index":3,"explanation":"Responsible visitors avoid disturbing animals and habitats. Follow local guidance and protect both people and wildlife."},{"question":"What are the three commonly used sustainability pillars?","options":["Environmental, social and economic","Advertising, colour and sound","Only profit, profit and profit","Transport, passports and luggage"],"correct_index":0,"explanation":"Sustainable tourism considers ecosystems, communities and economic viability together. A project can succeed financially while causing other harms."},{"question":"Why should marketing identify a target market?","options":["One message always suits everyone equally","Different visitors have different needs, budgets and interests","It removes the need to research customers","It guarantees every advertisement will succeed"],"correct_index":1,"explanation":"A defined market helps choose relevant products, messages and channels. Test assumptions through research and feedback."},{"question":"A lodge buys produce from nearby farmers. What benefit can this support?","options":["A guarantee of zero environmental impact","The elimination of all transport","Local economic linkages","An end to every seasonal job"],"correct_index":2,"explanation":"Local purchasing can retain more visitor spending in the area and support suppliers. Sustainability still requires considering quality, fairness and environmental effects."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Attractions and responsible tourism. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","tour"],"metadata":{"term":3,"focus":"Attractions and responsible tourism","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"3460b368-ba25-5b14-ab21-d0190c883aba","title":"Tourism · Grade 10 · Term 4: Culture, communication and customer care","subject":"Tourism","grade":"Grade 10","questions":[{"question":"Why should guides avoid stereotypes when describing a community's culture?","options":["Individuals and traditions are diverse and should be represented respectfully","Every person follows identical customs","Stereotypes are always accurate shortcuts","Visitors never need context"],"correct_index":0,"explanation":"Respectful interpretation recognises diversity and changing practices. Ask, research and avoid presenting a whole community as uniform."},{"question":"A guest says their booking is wrong. What is the best first response?","options":["Argue before checking evidence","Listen, clarify the details and check the booking record","Ignore the guest","Promise an impossible outcome immediately"],"correct_index":1,"explanation":"Customer care begins with listening and accurate information. Then explain practical options within the business's authority."},{"question":"Which written message is clearest for a guest?","options":["Come sometime soon.","It is happening there later.","Your tour departs from reception at 08:30 tomorrow; please arrive by 08:15.","You know the plan already."],"correct_index":2,"explanation":"Useful communication specifies action, place and time. Avoid assumptions and invite clarification where needed."},{"question":"Why conserve cultural heritage?","options":["It requires every tradition to stop changing","It exists only for tourists","It belongs to no living community","It can protect valued knowledge, places and practices for communities and future generations"],"correct_index":3,"explanation":"Heritage conservation should respect community meaning and participation. Tourism is one use, not the sole reason heritage matters."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Culture, communication and customer care. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","tour"],"metadata":{"term":4,"focus":"Culture, communication and customer care","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}}]$smartbridge$::jsonb)
